from lib import *
S = SS('n40')
steps = [
    step("c.File 只有一行:http.ServeFile(c.Writer, c.Request, filepath),所以 Range、If-Modified-Since、Content-Type 嗅探、目录重定向都是标准库的行为;FileAttachment 先设 Content-Disposition:文件名全是 ASCII 时用 attachment; filename=\"…\"(双引号和反斜杠被转义),含非 ASCII 时用 filename*=UTF-8''(url.QueryEscape 的结果),再 ServeFile。", t=tl(S(1)), mark=lidx(S(1), 'http.ServeFile(c.Writer, c.Request, filepath)', 'filename*=UTF-8'), done=lidx(S(1), 'func (c *Context) File(filepath string)', 'escapeQuotes(filename)'), kv=KV([['c.File', 'http.ServeFile'], ['ASCII 文件名', 'filename="…",引号被转义'], ['非 ASCII', 'filename*=UTF-8\'\'url.QueryEscape']], ['c.File'])),
    step("100 字节的文件,Range 请求:bytes=0-9 → 206,Content-Range: bytes 0-9/100,正文 10 字节;bytes=95- 与 bytes=-5 都是最后 5 字节(Content-Range: bytes 95-99/100);bytes=50-1000 被截到文件末尾(50-99);多段 bytes=0-4,10-14 → 206 multipart/byteranges;bytes=200-300 超出范围 → 416,Content-Range: bytes */100;bytes=5-2、bytes=abc、items=0-4 → 416 invalid range;HEAD + Range 也返回 206 与 Content-Length=10;对照 c.Data(没有 Range 支持,也没有 Accept-Ranges)总是 200 整个文件。", t=tl(S(2)), mark=lidx(S(2), 'bytes=200-300', 'bytes=5-2', 'bytes=abc', 'items=0-4', '对照 c.Data'), done=lidx(S(2), 'bytes=0-9"', 'bytes=95-', 'bytes=-5', 'bytes=50-1000', 'bytes=0-4,10-14', 'HEAD + Range'), kv=KV([['单段', '206 + Content-Range'], ['多段', 'multipart/byteranges'], ['越界 / 不合法', '416'], ['c.Data', '不支持 Range']], ['c.Data'])),
    step("If-Range:Range 加上 If-Range=Last-Modified(匹配)→ 206,10 字节;If-Range 是更早的日期(相当于文件变了)→ 200 返回整个文件;If-Range 是一个 ETag(服务端没有 ETag)→ 200 整个文件。断点续传时文件被改过,客户端就会拿到新的整个文件而不是拼出损坏的内容。", t=tl(S(3)), mark=lidx(S(3), '更早的日期', 'ETag'), done=lidx(S(3), 'If-Range=Last-Modified(匹配)'), kv=KV([['If-Range 匹配', '206 部分内容'], ['不匹配', '200 完整文件'], ['要用 ETag', '需要自己提供 ETag']], ['不匹配'])),
    step("FileAttachment 的 Content-Disposition:report.txt 与带空格的 my report.txt 是 filename=\"…\";a\"b.txt 里的引号被转义成 \\\";含中文的 报告.txt 是 filename*=UTF-8''%E6%8A%A5%E5%91%8A.txt;中 文.txt 的空格被编码成 +(%E4%B8%AD+%E6%96%87.txt),而 RFC 5987 的百分号编码里空格应该写 %20,+ 不会被还原成空格,浏览器可能把文件名显示成“中+文.txt”;résumé.txt 是 r%C3%A9sum%C3%A9.txt。", t=tl(S(4)), mark=lidx(S(4), '中 文.txt', '报告.txt'), done=lidx(S(4), 'report.txt', 'my report.txt', 'résumé.txt'), kv=KV([['ASCII', 'filename="…"'], ['非 ASCII', 'filename*=UTF-8\'\'… (QueryEscape)'], ['空格', '被写成 +,不是 %20']], ['空格'])),
    step("c.File 的路径来自用户时:ServeFile 只拒绝请求 URL 路径里的 ..,不检查你传给它的文件路径。c.File(filepath.Join(\"site/public\", c.Query(\"f\"))) 时,?f=../secret.txt 与 ?f=..%2fsecret.txt 都读到了根目录之外的文件(200,OUTSIDE-THE-ROOT);把路径放在通配参数里 /p/*name,/p/../secret.txt 与 /p/..%2fsecret.txt 则被 ServeFile 拒绝(400 invalid URL path)——因为这些 .. 出现在 URL 路径里。安全写法:filepath.Join(root, filepath.Clean(\"/\"+f)),/safe?f=../secret.txt → 404。", t=tl(S(5)), mark=lidx(S(5), '/q?f=../secret.txt', '/q?f=..%2fsecret.txt'), done=lidx(S(5), '/p/../secret.txt', '/p/..%2fsecret.txt', '/safe?f=../secret.txt'), b=bars([['查询参数拼接:读到根目录之外', 2, '2 / 2 成功读到'], ['URL 路径里的 ..:被拒绝', 2, '2 / 2 返回 400'], ['Clean("/"+f) 写法:越界请求', 0, '0 / 1 读到']], 2, mark=[0], done=[1, 2]), kv=KV([['查询参数里的 ../', 'ServeFile 不管,c.File 读到根外文件'], ['URL 路径里的 ..', 'ServeFile 拒绝(400)'], ['安全写法', 'Clean("/"+f) 后再 Join']], ['查询参数里的 ../'])),
    step("200 MiB 的文件,服务一次的进程累计分配:c.File 增加 0.7 MiB(流式发送);先 os.ReadFile 再 c.Data 增加 200.1 MiB(整个文件读进内存);c.DataFromReader(Content-Length、额外头 X-Extra: yes)增加 0.0 MiB。三种方式客户端都收到 200 MiB 与正确的 Content-Length。", t=tl(S(6)), mark=lidx(S(6), '/data'), done=lidx(S(6), '/file', '/reader'), b=bars([['c.File', 0.7, '0.7 MiB'], ['ReadFile + c.Data', 200.1, '200.1 MiB'], ['DataFromReader', 0.0, '0.0 MiB']], 200.1, done=[0, 2], mark=[1]), kv=KV([['c.File / DataFromReader', '流式,分配几乎为 0'], ['ReadFile + c.Data', '分配 = 文件大小'], ['DataFromReader', '自己设 Content-Length,不支持 Range']], ['ReadFile + c.Data'])),
]
A = mkartn('n40', 40, 'Gin,c.File,Range请求,FileAttachment,文件下载,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测文件下载:c.File 就是 http.ServeFile,支持 Range(单段 206、多段 multipart/byteranges、越界 416)与 If-Range;c.Data 没有 Range;FileAttachment 对非 ASCII 文件名把空格编码成 +;c.File 拼接查询参数能读到根目录之外的文件;200 MiB 文件 c.File 只分配 0.7 MiB。',
    '下载大文件、断点续传、中文文件名、c.File 的路径从哪来——这些在 Gin 里都归 c.File 与 FileAttachment 管。这篇用真实的 Range 请求和 200 MiB 文件测它们的行为,并重点验证一个常见的安全坑:把用户给的路径交给 c.File。',
    [('416', 'Range: bytes=200-300 超出 100 字节文件:416,Content-Range: bytes */100'), ('200 + 根外文件', 'c.File(Join(root, c.Query("f"))) 在 ?f=../secret.txt 时读到了根目录之外的文件'), ('0.7 vs 200.1 MiB', '200 MiB 文件用 c.File 与 ReadFile + c.Data 服务一次的累计分配')],
    [('c.File 就是 ServeFile', '<p><code>c.File</code> 只有一行 <code>http.ServeFile</code>,所以它继承了标准库的全部能力:<code>Range</code>、<code>If-Range</code>、<code>If-Modified-Since</code>、按扩展名与嗅探确定 Content-Type、目录请求的重定向。<code>FileAttachment</code> 只是多设了一个 <code>Content-Disposition</code>。</p>'),
     ('Range 请求', '<p>单段 Range 返回 206 与 <code>Content-Range</code>;<code>bytes=95-</code>、<code>bytes=-5</code> 都表示末尾,超出文件末尾的上界被截断;多段返回 <code>multipart/byteranges</code>;起点超出文件或语法不对返回 416(起点越界时带 <code>Content-Range: bytes */总长度</code>)。HEAD 加 Range 同样返回 206。<code>c.Data</code> / <code>c.String</code> 没有这些,Range 请求总是返回整个内容,也没有 <code>Accept-Ranges</code>。</p>'),
     ('断点续传', '<p><code>If-Range</code> 用 <code>Last-Modified</code> 做条件:匹配就返回部分内容,文件变过就返回完整文件,避免拼出损坏的文件。服务端没有 <code>ETag</code>,所以带 ETag 的 <code>If-Range</code> 总是退化成 200 整个文件。</p>'),
     ('FileAttachment 的文件名', '<p>纯 ASCII 文件名用 <code>filename="…"</code>(转义引号与反斜杠);含非 ASCII 用 RFC 5987 的 <code>filename*=UTF-8\'\'…</code>,但编码用的是 <code>url.QueryEscape</code>,空格变成 <code>+</code> 而不是 <code>%20</code>,带空格的中文文件名在浏览器里可能显示成加号。需要时自己拼 <code>Content-Disposition</code>。</p>'),
     ('用户给的路径', '<p><code>ServeFile</code> 只检查请求 URL 的路径里有没有 <code>..</code>,并不检查你传给它的文件名。把查询参数拼进路径,<code>../</code> 就能读到根目录之外的文件。写法是 <code>filepath.Join(root, filepath.Clean("/"+f))</code>,让 Clean 先把 <code>..</code> 吃掉;更好的做法是用 ID 查文件,不接受路径。</p>'),
     ('大文件', '<p><code>c.File</code> 和 <code>DataFromReader</code> 都是流式发送,累计分配几乎为零;先 <code>ReadFile</code> 再 <code>c.Data</code> 会把整个文件读进内存,并发下载时内存与文件大小成正比。<code>DataFromReader</code> 要自己提供 Content-Length,也不支持 Range。</p>')],
    steps,
    [ENV_N_GIN + '。用真实的 httptest.NewServer;Range 请求用 http.Transport.RoundTrip 手工构造,避免客户端自动处理;文件是实验时在程序目录里创建的(200 MiB 的稀疏文件,实验后删除);累计分配用 runtime.ReadMemStats 的 TotalAlloc 差,每种方式各一次',
     '没有验证:浏览器对 filename* 里 + 的显示(只验证了服务端输出);并发 Range 下载的性能;Windows 路径的处理;符号链接与 c.File 的关系;sendfile 零拷贝是否真的被使用(只测了 Go 层面的分配);HTTP/2 下的 Range'],
    '文件下载与 Range')
